sys_script_include.script:
var HoCOHSMFluClinic = Class.create();
HoCOHSMFluClinic.prototype = {
    initialize: function() {},
    isAllowedToSelectOthers: function() {
        var isOHSAdvisor = gs.hasRole("x_hccc_hoc_ohs.advisor");
        var isWellness = gs.hasRole("x_hccc_hoc_ohs.wellness");
        var isNurse = gs.hasRole("sn_walkup.walkup_technician") || gs.hasRole("sn_csm_walkup.walkup_technician");

        var gr = new GlideRecord("sys_user");
        gr.get(gs.getUserID());
        gr.query();
        gr.next();
        var isMPStaff = gr.getValue("x_hccc_base_user_type") == "mp_staff";
        var isPPS = gr.getValue("x_hccc_base_user_type") == "pps";

        return isOHSAdvisor || isWellness || isNurse || isMPStaff || isPPS;
    },
    createExternalContact: function(first_name, last_name, email) {
        var grContactSearch = new GlideRecord('customer_contact');
        grContactSearch.addQuery('email', email);
        grContactSearch.query();
        if (grContactSearch.next()) {
            return grContactSearch.sys_id; //return sys_id to populate the reference field

        } else {
            //need to create the contact and return the sys_id.
            var grNewContact = new GlideRecord('customer_contact');
            grNewContact.initialize();
            grNewContact.first_name = first_name;
            grNewContact.last_name = last_name;
            grNewContact.x_hccc_base_display_name = first_name + " " + last_name;
            grNewContact.email = email;
            grNewContact.insert();

            return grNewContact.sys_id;
        }
    },
    alreadyHaveAppointment: function() {
        var userSysId = gs.getUserID();
        var gr = new GlideRecord('wu_appointment');
        gr.addEncodedQuery('stateNOT IN3,4,7^active=true^contactDYNAMIC90d1921e5f510100a9ad2572f2b477fe');
        gr.query();
        return gr.getRowCount() >= 1;

    },
    type: 'HoCOHSMFluClinic'
};
